INSERT INTO skills (code, subject_code, name) VALUES
    ('ADD_10_K', 'MATH', 'Addition and Subtraction within 10'),
    ('QUESTION_WORDS_K', 'ENGLISH', 'Question Words');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('13000000-0000-0000-0000-000000000018', 'K-ADD10-01', 'MATH', 'KINDERGARTEN', 10, 'Adding and Taking Away within 10', 'Put together and take apart groups up to 10.'),
    ('13000000-0000-0000-0000-000000000019', 'K-ENG-QWORD-01', 'ENGLISH', 'KINDERGARTEN', 9, 'Who, What, and Where', 'Use question words to find answers in a story.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('33000000-0000-0000-0000-000000000001', 'K-COUNT-01', 'COUNT_20', 4, 'What number comes after 11?', 1, 'We count 10, 11, 12. After 11 comes 12.', 'Count up from 10.'),
    ('33000000-0000-0000-0000-000000000002', 'K-COUNT-01', 'COUNT_20', 5, 'Count up: 7, 8, 9, __?', 2, 'After 9 comes 10.', 'What comes after 9?'),
    ('33000000-0000-0000-0000-000000000003', 'K-COUNT-01', 'COUNT_20', 6, 'What number comes before 13?', 1, 'We count 11, 12, 13. Before 13 comes 12.', 'Count up and stop just before 13.'),
    ('33000000-0000-0000-0000-000000000004', 'K-COUNT100-01', 'COUNT_100_10S', 4, 'Count by tens: 20, 30, 40, __?', 2, 'Counting by tens: 20, 30, 40, 50.', 'Add one more ten.'),
    ('33000000-0000-0000-0000-000000000005', 'K-COUNT100-01', 'COUNT_100_10S', 5, 'Count by tens: 60, 70, 80, __?', 0, '60, 70, 80, 90.', 'Six-ty, seven-ty, eigh-ty, ...'),
    ('33000000-0000-0000-0000-000000000006', 'K-COUNT100-01', 'COUNT_100_10S', 6, 'Which number comes first when counting by tens from 10?', 1, 'Counting by tens starts 10, 20, 30...', 'Where do you start?'),
    ('33000000-0000-0000-0000-000000000007', 'K-WRITE-01', 'WRITE_NUM', 4, 'Which number is written as "fifteen"?', 0, 'Fifteen is 15.', 'It is a teen number.'),
    ('33000000-0000-0000-0000-000000000008', 'K-WRITE-01', 'WRITE_NUM', 5, 'Which number is written as "zero"?', 2, 'Zero means none: 0.', 'How many do you have if you have nothing?'),
    ('33000000-0000-0000-0000-000000000009', 'K-WRITE-01', 'WRITE_NUM', 6, 'Which number is written as "twenty"?', 2, 'Twenty is 20.', 'Two tens.'),
    ('33000000-0000-0000-0000-000000000010', 'K-ADD5-01', 'ADD_5', 4, 'What is 3 + 2?', 2, '3 + 2 = 5.', 'Hold up 3 fingers, then 2 more.'),
    ('33000000-0000-0000-0000-000000000011', 'K-ADD5-01', 'ADD_5', 5, 'What is 4 + 0?', 2, 'Adding 0 changes nothing: 4 + 0 = 4.', 'Adding zero adds nothing.'),
    ('33000000-0000-0000-0000-000000000012', 'K-ADD5-01', 'ADD_5', 6, 'You have 1 apple and get 1 more. How many apples now?', 2, '1 + 1 = 2.', 'One and one more.'),
    ('33000000-0000-0000-0000-000000000013', 'K-SUB5-01', 'SUB_5', 4, 'What is 5 - 1?', 1, '5 - 1 = 4.', 'Count back one from 5.'),
    ('33000000-0000-0000-0000-000000000014', 'K-SUB5-01', 'SUB_5', 5, 'What is 4 - 2?', 2, '4 - 2 = 2.', 'Hold up 4 fingers and put 2 down.'),
    ('33000000-0000-0000-0000-000000000015', 'K-SUB5-01', 'SUB_5', 6, 'There are 3 birds. 3 fly away. How many are left?', 0, '3 - 3 = 0. None are left!', 'All of them flew away.'),
    ('33000000-0000-0000-0000-000000000016', 'K-COMPARE-01', 'COMPARE_K', 4, 'Which group has more: 6 cars or 4 cars?', 0, '6 is more than 4.', 'Count each group.'),
    ('33000000-0000-0000-0000-000000000017', 'K-COMPARE-01', 'COMPARE_K', 5, 'Which number is less: 9 or 7?', 2, '7 is less than 9.', 'Which comes first when counting?'),
    ('33000000-0000-0000-0000-000000000018', 'K-COMPARE-01', 'COMPARE_K', 6, 'Are 5 hats and 3 hats equal groups?', 1, '5 and 3 are different numbers, so the groups are not equal.', 'Are the numbers the same?'),
    ('33000000-0000-0000-0000-000000000019', 'K-SHAPE-01', 'SHAPES_K', 4, 'Which shape has 3 corners?', 2, 'A triangle has 3 corners.', 'Count the pointy parts.'),
    ('33000000-0000-0000-0000-000000000020', 'K-SHAPE-01', 'SHAPES_K', 5, 'Which shape has 6 sides?', 2, 'A hexagon has 6 sides.', 'Like a honeycomb.'),
    ('33000000-0000-0000-0000-000000000021', 'K-SHAPE-01', 'SHAPES_K', 6, 'Which shape is like a ball, not flat?', 0, 'A sphere is round all over like a ball. A circle is flat.', 'You can hold it in your hands.'),
    ('33000000-0000-0000-0000-000000000022', 'K-MEASURE-01', 'MEASURE_K', 4, 'A bus and a bike. Which one is longer?', 0, 'A bus is much longer than a bike.', 'Which one carries lots of people?'),
    ('33000000-0000-0000-0000-000000000023', 'K-MEASURE-01', 'MEASURE_K', 5, 'A cup and a bucket. Which one holds more water?', 0, 'A bucket is bigger, so it holds more water.', 'Which one is bigger?'),
    ('33000000-0000-0000-0000-000000000024', 'K-MEASURE-01', 'MEASURE_K', 6, 'A feather and a rock. Which one is heavier?', 1, 'A rock is much heavier than a feather.', 'Which one is hard to lift?'),
    ('33000000-0000-0000-0000-000000000025', 'K-PATTERN-01', 'PATTERNS_K', 4, 'What comes next: A, B, C, A, B, __?', 1, 'The pattern is A, B, C. After B comes C.', 'Find the part that repeats.'),
    ('33000000-0000-0000-0000-000000000026', 'K-PATTERN-01', 'PATTERNS_K', 5, 'What comes next: sun, moon, sun, moon, __?', 2, 'The pattern is sun, moon. Next is sun.', 'Say it out loud.'),
    ('33000000-0000-0000-0000-000000000027', 'K-PATTERN-01', 'PATTERNS_K', 6, 'What comes next: 1, 1, 2, 1, 1, __?', 1, 'The pattern is 1, 1, 2. Next is 2.', 'What repeats?'),
    ('33000000-0000-0000-0000-000000000028', 'K-ENG-SIGHT-01', 'SIGHT_WORDS_K', 4, 'Which word is "and"?', 2, '"and" is spelled a-n-d.', 'Look at all three letters.'),
    ('33000000-0000-0000-0000-000000000029', 'K-ENG-SIGHT-01', 'SIGHT_WORDS_K', 5, 'Which word is "is"?', 2, '"is" is spelled i-s.', 'Look at the last letter.'),
    ('33000000-0000-0000-0000-000000000030', 'K-ENG-SIGHT-01', 'SIGHT_WORDS_K', 6, 'Which word is "you"?', 1, '"you" is spelled y-o-u.', 'Three letters, ending in u.'),
    ('33000000-0000-0000-0000-000000000031', 'K-ENG-SOUNDS-01', 'LETTER_SOUNDS_K', 4, 'What sound does the letter "T" make?', 2, 'T makes the tuh sound, like in top.', 'Think of "top".'),
    ('33000000-0000-0000-0000-000000000032', 'K-ENG-SOUNDS-01', 'LETTER_SOUNDS_K', 5, 'What sound does the letter "F" make?', 0, 'F makes the fff sound, like in fan.', 'Think of "fan".'),
    ('33000000-0000-0000-0000-000000000033', 'K-ENG-SOUNDS-01', 'LETTER_SOUNDS_K', 6, 'What sound does the letter "B" make?', 1, 'B makes the buh sound, like in ball.', 'Think of "ball".'),
    ('33000000-0000-0000-0000-000000000034', 'K-ENG-CVC-01', 'CVC_WORDS', 4, 'What word is spelled H-A-T?', 0, 'H-a-t spells hat.', 'Say each sound: h, a, t.'),
    ('33000000-0000-0000-0000-000000000035', 'K-ENG-CVC-01', 'CVC_WORDS', 5, 'What word is spelled P-I-G?', 1, 'P-i-g spells pig.', 'Say each sound: p, i, g.'),
    ('33000000-0000-0000-0000-000000000036', 'K-ENG-CVC-01', 'CVC_WORDS', 6, 'What word is spelled B-E-D?', 2, 'B-e-d spells bed.', 'Say each sound: b, e, d.'),
    ('33000000-0000-0000-0000-000000000037', 'K-ENG-RHYME-01', 'RHYMING_K', 4, 'Which word rhymes with "cake"?', 0, 'Cake and lake end in -ake.', 'Listen to the end.'),
    ('33000000-0000-0000-0000-000000000038', 'K-ENG-RHYME-01', 'RHYMING_K', 5, 'Which word rhymes with "map"?', 0, 'Map and cap end in -ap.', 'M-ap, c-ap.'),
    ('33000000-0000-0000-0000-000000000039', 'K-ENG-RHYME-01', 'RHYMING_K', 6, 'Which word rhymes with "king"?', 2, 'King and ring end in -ing.', 'K-ing, r-ing.'),
    ('33000000-0000-0000-0000-000000000040', 'K-ENG-SEQUENCE-01', 'SEQUENCING_K', 4, 'First Ava put on socks, then she put on shoes. What did Ava do first?', 2, 'Ava put on socks first, then shoes.', 'Listen for "first".'),
    ('33000000-0000-0000-0000-000000000041', 'K-ENG-SEQUENCE-01', 'SEQUENCING_K', 5, 'Ben poured milk, then he drank it. What happened last?', 1, 'First he poured, then he drank. Drinking happened last.', 'Listen for "then".'),
    ('33000000-0000-0000-0000-000000000042', 'K-ENG-SEQUENCE-01', 'SEQUENCING_K', 6, 'The snowman melted after the sun came out. What happened first?', 0, '"After" tells us the sun came out first, then the snowman melted.', 'What does "after" tell you?'),
    ('33000000-0000-0000-0000-000000000043', 'K-ENG-BEGINEND-01', 'BEGIN_END_SOUNDS', 4, 'What is the beginning sound in "moon"?', 2, 'Moon starts with mmm.', 'Close your lips.'),
    ('33000000-0000-0000-0000-000000000044', 'K-ENG-BEGINEND-01', 'BEGIN_END_SOUNDS', 5, 'What is the ending sound in "bus"?', 1, 'Bus ends with sss.', 'Listen to the very end.'),
    ('33000000-0000-0000-0000-000000000045', 'K-ENG-BEGINEND-01', 'BEGIN_END_SOUNDS', 6, 'What is the ending sound in "dog"?', 2, 'Dog ends with the g sound.', 'Do-g.'),
    ('33000000-0000-0000-0000-000000000046', 'K-ENG-SENTENCE-01', 'SIMPLE_SENTENCES', 4, 'Read: "The dog can run." What can the dog do?', 2, 'The sentence says the dog can run.', 'Find the last word.'),
    ('33000000-0000-0000-0000-000000000047', 'K-ENG-SENTENCE-01', 'SIMPLE_SENTENCES', 5, 'Read: "I have a red hat." What color is the hat?', 0, 'The hat is red.', 'Find the color word.'),
    ('33000000-0000-0000-0000-000000000048', 'K-ENG-SENTENCE-01', 'SIMPLE_SENTENCES', 6, 'Read: "Mom is in the car." Where is Mom?', 0, 'The sentence says Mom is in the car.', 'Find where Mom is.'),
    ('33000000-0000-0000-0000-000000000049', 'K-ENG-NOUNS-01', 'NOUNS_K', 4, 'Which word names a place?', 0, 'A park is a place.', 'Where can you go?'),
    ('33000000-0000-0000-0000-000000000050', 'K-ENG-NOUNS-01', 'NOUNS_K', 5, 'Which word names a person?', 0, 'A teacher is a person.', 'Who helps you learn?'),
    ('33000000-0000-0000-0000-000000000051', 'K-ENG-NOUNS-01', 'NOUNS_K', 6, 'Which word is a naming word in "The cat naps"?', 2, 'Cat names an animal.', 'Who is napping?'),
    ('33000000-0000-0000-0000-000000000052', 'K-ADD10-01', 'ADD_10_K', 1, 'What is 5 + 3?', 0, '5 + 3 = 8.', 'Start at 5 and count up 3.'),
    ('33000000-0000-0000-0000-000000000053', 'K-ADD10-01', 'ADD_10_K', 2, 'What is 6 + 4?', 2, '6 + 4 = 10.', 'Use your 10 fingers.'),
    ('33000000-0000-0000-0000-000000000054', 'K-ADD10-01', 'ADD_10_K', 3, 'What is 8 - 2?', 1, '8 - 2 = 6.', 'Count back 2 from 8.'),
    ('33000000-0000-0000-0000-000000000055', 'K-ADD10-01', 'ADD_10_K', 4, 'What is 10 - 5?', 1, '10 - 5 = 5.', 'Put down one whole hand.'),
    ('33000000-0000-0000-0000-000000000056', 'K-ADD10-01', 'ADD_10_K', 5, 'You have 4 blocks and get 3 more. How many blocks now?', 1, '4 + 3 = 7.', 'Count up 3 from 4.'),
    ('33000000-0000-0000-0000-000000000057', 'K-ADD10-01', 'ADD_10_K', 6, '7 frogs sit on a log. 3 hop away. How many are left?', 1, '7 - 3 = 4.', 'Hopping away means take away.'),
    ('33000000-0000-0000-0000-000000000058', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 1, 'Read: "Sam ate an apple." Who ate the apple?', 0, '"Who" asks about a person: Sam.', '"Who" asks about a person.'),
    ('33000000-0000-0000-0000-000000000059', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 2, 'Read: "Sam ate an apple." What did Sam eat?', 1, '"What" asks about a thing: an apple.', '"What" asks about a thing.'),
    ('33000000-0000-0000-0000-000000000060', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 3, 'Read: "The cat sat on the bed." Where did the cat sit?', 0, '"Where" asks about a place: on the bed.', '"Where" asks about a place.'),
    ('33000000-0000-0000-0000-000000000061', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 4, 'Which word asks about a place?', 2, '"Where" asks about a place.', 'Where are you?'),
    ('33000000-0000-0000-0000-000000000062', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 5, 'Which word asks about a person?', 2, '"Who" asks about a person.', 'Who is your friend?'),
    ('33000000-0000-0000-0000-000000000063', 'K-ENG-QWORD-01', 'QUESTION_WORDS_K', 6, 'Read: "At night, the owl hoots." When does the owl hoot?', 2, '"When" asks about time: at night.', '"When" asks about time.');
